# XOR analysis of encrypted exports
python3 << 'PYEOF'
import subprocess, json

# Get all ciphertexts
items = {}
for item_id in ["vault", "1", "2", "3", "4", "5"]:
    result = subprocess.run([
        "curl", "-s", "-b", "/tmp/cookies.txt",
        f"http://10.200.89.2:3000/exports/encrypted?item={item_id}",
        "--connect-timeout", "5", "--max-time", "8"
    ], capture_output=True, text=True, timeout=10)
    try:
        data = json.loads(result.stdout)
        items[item_id] = bytes.fromhex(data.get("cipher_hex", ""))
    except:
        pass

print("Ciphertext lengths:")
for k, v in items.items():
    print(f"  {k}: {len(v)} bytes")

# Check if items 2-5 share same prefix
print("\nComparing items:")
for k1 in items:
    for k2 in items:
        if k1 < k2:
            common = 0
            for i in range(min(len(items[k1]), len(items[k2]))):
                if items[k1][i] == items[k2][i]:
                    common += 1
                else:
                    break
            print(f"  {k1} vs {k2}: {common} common prefix bytes")

# XOR ciphertexts to see if same plaintext with different keys
print("\nXOR analysis (items with same key should XOR to 0):")
# XOR vault with item 1
if "vault" in items and "1" in items:
    minlen = min(len(items["vault"]), len(items["1"]))
    xor_result = bytes(a ^ b for a, b in zip(items["vault"][:minlen], items["1"][:minlen]))
    print(f"  vault XOR 1: {xor_result.hex()}")

# XOR item 2 with item 1
if "2" in items and "1" in items:
    minlen = min(len(items["2"]), len(items["1"]))
    xor_result = bytes(a ^ b for a, b in zip(items["2"][:minlen], items["1"][:minlen]))
    print(f"  2 XOR 1: {xor_result.hex()}")

# Check if items 2-5 are identical (same ciphertext = same plaintext)
for i in [2, 3, 4, 5]:
    if str(i) in items and "2" in items:
        if items[str(i)] == items["2"]:
            print(f"  item {i} == item 2 (IDENTICAL)")
        elif items[str(i)][:len(items["2"])] == items["2"]:
            print(f"  item {i} starts with item 2, extra: {items[str(i)][len(items['2']):].hex()}")
PYEOF

